/* Tool database with fill-in templates. No acronyms anywhere a person reads.
   e: 3 strong, 2 moderate, 1 emerging, 0 not rated. c: main target, C capability, O opportunity, M motivation.
   fit: cue, avoid, thought, deep, start. b: technique numbers from the Behaviour Change Technique Taxonomy, version 1.
   tp: the template. Field kinds: text, long, rate, num, choice, multi, date, time, list, table, grid, head, info, calc. */
const T = (k, l, p) => ({ t: "text", k: k, l: l, p: p || "" });
const L = (k, l, p) => ({ t: "long", k: k, l: l, p: p || "" });
const R = (k, l, max) => ({ t: "rate", k: k, l: l, max: max || 10 });
const N = (k, l, u) => ({ t: "num", k: k, l: l, u: u || "" });
const C = (k, l, o) => ({ t: "choice", k: k, l: l, o: o });
const M = (k, l, o) => ({ t: "multi", k: k, l: l, o: o });
const D = (k, l) => ({ t: "date", k: k, l: l });
const TM = (k, l) => ({ t: "time", k: k, l: l });
const LI = (k, l, n, p) => ({ t: "list", k: k, l: l, n: n || 3, p: p || "" });
const TB = (k, l, cols, n, rows) => ({ t: "table", k: k, l: l, cols: cols, n: n || 3, rows: rows || null });
const G = (k, l, rows, max) => ({ t: "grid", k: k, l: l, rows: rows, max: max || 10 });
const H = (l) => ({ t: "head", l: l });
const I = (l) => ({ t: "info", l: l });
const DIFF = (a, b, l, unit) => ({ t: "calc", fn: "diff", a: a, b: b, l: l || "Change", u: unit || "points" });

const YN = ["Yes", "Partly", "No"];
